        diff = [int(start[i] != target[i]) for i in range(n)]
        best = None
        for mask in range(1 << (n - 1)):
            par = [0] * n
            cnt = 0
            for i in range(n - 1):
                if mask >> i & 1:
                    par[edges[i][0]] ^= 1
                    par[edges[i][1]] ^= 1
                    cnt += 1
            if par == diff and (best is None or cnt < len(best)):
                best = [i for i in range(n - 1) if mask >> i & 1]
        return sorted(best) if best is not None else [-1]

