class Solution {
public:
    vector<int> minEdgeToggles(int n, vector<vector<int>>& edges, string start, string target) {
        vector<int> diff(n);
        for (int i = 0; i < n; i++) diff[i] = start[i] != target[i];
        vector<int> best;
        for (int mask = 0; mask < (1 << (n - 1)); mask++) {
            vector<int> par(n, 0);
            for (int i = 0; i < n - 1; i++)
                if (mask >> i & 1) { par[edges[i][0]] ^= 1; par[edges[i][1]] ^= 1; }
            if (par == diff) {
                vector<int> cur;
                for (int i = 0; i < n - 1; i++) if (mask >> i & 1) cur.push_back(i);
                if (best.empty() || cur.size() < best.size()) best = cur;
            }
        }
        if (best.empty()) return {-1};
        sort(best.begin(), best.end());
        return best;
    }
};

