from collections import defaultdict
class Solution:
    def minEdgeToggles(self, n, edges, start, target):
        if sum(start[i] != target[i] for i in range(n)) % 2:
            return [-1]
        adj = defaultdict(list)
        for i, (u, v) in enumerate(edges):
            adj[u].append((v, i))
            adj[v].append((u, i))
        deg = [len(adj[x]) for x in range(n)]
        par = [False] * n
        removed = [False] * n
        stack = [x for x in range(n) if deg[x] <= 1]
        res = []
        while stack:
            x = stack.pop()
            if removed[x]:
                continue
            removed[x] = True
            for y, idx in adj[x]:
                if removed[y]:
                    continue
                if par[x]:
                    res.append(idx)
                    par[y] ^= True
                deg[y] -= 1
                if deg[y] <= 1:
                    stack.append(y)
        return sorted(res)

