class Solution {
public:
    vector<int> minEdgeToggles(int n, vector<vector<int>>& edges, string start, string target) {
        int need = 0;
        for (int i = 0; i < n; i++) need += start[i] != target[i];
        if (need % 2) return {-1};
        vector<vector<pair<int,int>>> adj(n);
        for (int i = 0; i < n - 1; i++) {
            adj[edges[i][0]].push_back({edges[i][1], i});
            adj[edges[i][1]].push_back({edges[i][0], i});
        }
        vector<int> deg(n), par(n, 0), res;
        vector<bool> removed(n, false);
        stack<int> st;
        for (int x = 0; x < n; x++) { deg[x] = adj[x].size(); if (deg[x] <= 1) st.push(x); }
        while (!st.empty()) {
            int x = st.top(); st.pop();
            if (removed[x]) continue;
            removed[x] = true;
            for (auto& [y, idx] : adj[x]) {
                if (removed[y]) continue;
                if (par[x]) { res.push_back(idx); par[y] ^= 1; }
                if (--deg[y] <= 1) st.push(y);
            }
        }
        sort(res.begin(), res.end());
        return res;
    }
};

