class Solution {
    public int[] minEdgeToggles(int n, int[][] edges, String start, String target) {
        int need = 0;
        for (int i = 0; i < n; i++) if (start.charAt(i) != target.charAt(i)) need++;
        if (need % 2 == 1) return new int[]{-1};
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int i = 0; i < n - 1; i++) {
            adj.get(edges[i][0]).add(new int[]{edges[i][1], i});
            adj.get(edges[i][1]).add(new int[]{edges[i][0], i});
        }
        int[] deg = new int[n], par = new int[n];
        boolean[] removed = new boolean[n];
        Deque<Integer> st = new ArrayDeque<>();
        List<Integer> res = new ArrayList<>();
        for (int x = 0; x < n; x++) { deg[x] = adj.get(x).size(); if (deg[x] <= 1) st.push(x); }
        while (!st.isEmpty()) {
            int x = st.pop();
            if (removed[x]) continue;
            removed[x] = true;
            for (int[] e : adj.get(x)) {
                int y = e[0], idx = e[1];
                if (removed[y]) continue;
                if (par[x] == 1) { res.add(idx); par[y] ^= 1; }
                if (--deg[y] <= 1) st.push(y);
            }
        }
        int[] ans = res.stream().mapToInt(Integer::intValue).toArray();
        java.util.Arrays.sort(ans);
        return ans;
    }
}

